def page(name,title,body):
 s=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#7258b6"><title>{title} · Nident</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/styles.css?v=4"><link rel="stylesheet" href="css/nident.css?v=4"></head><body class="nident {name}">{header(name)}<main id="contenido" class="wrap">{body}</main>{footer}<script src="js/main.js?v=4"></script><script src="js/nident.js?v=4"></script></body></html>'''
 (root/f'{name}.html').write_text(s,encoding='utf-8')

